ALTER TABLE orders ADD COLUMN voucher_code VARCHAR(255) NULL, ADD COLUMN voucher_discount BIGINT NULL, ADD COLUMN shipping_fee BIGINT NULL;
CREATE TABLE IF NOT EXISTS vouchers (id BIGINT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(32) NOT NULL UNIQUE,kind VARCHAR(255),value BIGINT NOT NULL,maximum_discount BIGINT NOT NULL,minimum_subtotal BIGINT NOT NULL,starts_at DATETIME(6),expires_at DATETIME(6),usage_limit INT NOT NULL,per_user_limit INT NOT NULL,active BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS voucher_uses (id BIGINT AUTO_INCREMENT PRIMARY KEY,voucher_id BIGINT NOT NULL,owner_id BIGINT NOT NULL,order_id BIGINT NOT NULL UNIQUE,discount BIGINT NOT NULL,KEY ix_voucher_owner(voucher_id,owner_id),FOREIGN KEY (voucher_id) REFERENCES vouchers(id),FOREIGN KEY (order_id) REFERENCES orders(orders_id));
